package com.bank.flink.async;

import java.util.concurrent.CompletableFuture;

// A genuinely asynchronous external client: returns a future, does NOT block.
class BureauClient {

    // Each call takes ~20ms but runs concurrently on the common pool.
    CompletableFuture<Integer> lookupRiskAsync(String accountId) {
        return CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(20); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            return Math.abs(accountId.hashCode()) % 100; // risk score 0..99
        });
    }
}
