package com.bank.flink.async;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.logging.Logger;

// Models Flink Async I/O: issues all lookups concurrently, then completes
// either in completion order (unordered) or input order (ordered).
class AsyncEnricher {
    private static final Logger log = Logger.getLogger(AsyncEnricher.class.getName());
    private final BureauClient client;
    private final long timeoutMs;

    AsyncEnricher(BureauClient client, long timeoutMs) {
        this.client = client;
        this.timeoutMs = timeoutMs;
    }

    // Synchronous baseline: one blocking call at a time.
    List<EnrichedTxn> enrichSync(List<Txn> txns) throws Exception {
        List<EnrichedTxn> out = new ArrayList<>();
        for (Txn t : txns) {
            int score = client.lookupRiskAsync(t.getAccountId()).get(); // blocks each time
            out.add(new EnrichedTxn(t.getTxnId(), score));
        }
        return out;
    }

    // Unordered async: fire all, collect in completion order.
    List<EnrichedTxn> enrichUnordered(List<Txn> txns) {
        List<CompletableFuture<EnrichedTxn>> futures = new ArrayList<>();
        for (Txn t : txns) {
            futures.add(client.lookupRiskAsync(t.getAccountId())
                    .orTimeout(timeoutMs, TimeUnit.MILLISECONDS)
                    .exceptionally(ex -> -1) // timeout fallback score
                    .thenApply(score -> new EnrichedTxn(t.getTxnId(), score)));
        }
        List<EnrichedTxn> out = new ArrayList<>();
        // Collect as they complete (completion order).
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
        for (CompletableFuture<EnrichedTxn> f : futures) out.add(f.join());
        return out;
    }

    // Ordered async: fire all concurrently, but output follows input order.
    List<EnrichedTxn> enrichOrdered(List<Txn> txns) {
        List<CompletableFuture<EnrichedTxn>> futures = new ArrayList<>();
        for (Txn t : txns) {
            futures.add(client.lookupRiskAsync(t.getAccountId())
                    .orTimeout(timeoutMs, TimeUnit.MILLISECONDS)
                    .exceptionally(ex -> -1)
                    .thenApply(score -> new EnrichedTxn(t.getTxnId(), score)));
        }
        // Join in input order -> preserves order while still concurrent.
        List<EnrichedTxn> out = new ArrayList<>();
        for (CompletableFuture<EnrichedTxn> f : futures) out.add(f.join());
        return out;
    }
}
