package com.bank.flink.async;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AsyncIoDemo {
    private static final Logger log = Logger.getLogger(AsyncIoDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) throws Exception {
        List<Txn> txns = new ArrayList<>();
        for (int i = 1; i <= 20; i++) {
            txns.add(new Txn("T" + i, (i % 2 == 0 ? "CUR" : "SAV") + (3000 + i),
                    new BigDecimal(1000 * i)));
        }
        AsyncEnricher enricher = new AsyncEnricher(new BureauClient(), 500);

        long t0 = System.currentTimeMillis();
        enricher.enrichSync(txns);
        log.info("SYNC took " + (System.currentTimeMillis() - t0) + "ms");

        long t1 = System.currentTimeMillis();
        List<EnrichedTxn> unordered = enricher.enrichUnordered(txns);
        log.info("UNORDERED async took " + (System.currentTimeMillis() - t1) + "ms, first="
                + unordered.get(0));

        long t2 = System.currentTimeMillis();
        List<EnrichedTxn> ordered = enricher.enrichOrdered(txns);
        log.info("ORDERED async took " + (System.currentTimeMillis() - t2) + "ms, first="
                + ordered.get(0) + " last=" + ordered.get(ordered.size() - 1));
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
